import gurobipy as gp
from gurobipy import GRB
vehicle_names = ['Sedan', 'SUV', 'Truck', 'Convertible', 'Minivan', 'Coupe', 'Hatchback', 'Station Wagon', 'Electric Car', 'Hybrid Car', 'Luxury Sedan', 'Sports Car', 'Crossover', 'Diesel Truck', 'Compact SUV', 'Luxury SUV', 'Cargo Van', 'Pickup Truck', 'Roadster', 'Muscle Car', 'Off-road Vehicle', 'Camper Van', 'Compact Car', 'Motorcycle', 'Electric SUV']
profit = {}
weight = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'ProductName' in v and v['ProductName'] in vehicle_names:
        name = v['ProductName']
        profit[name] = int(v['Value'])
        weight[name] = int(v['Weight'])
missing = [name for name in vehicle_names if name not in profit or name not in weight]
if missing:
    raise ValueError(f'Missing data for vehicles: {missing}')
capacity = None
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'Capacity' in v:
        capacity = int(v['Capacity'])
        break
if capacity is None:
    raise ValueError('Total capacity not found in LEGACY_RECORDS.')
m = gp.Model('Car_Inventory_Optimization')
x = m.addVars(vehicle_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((profit[name] * x[name] for name in vehicle_names)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[name] * x[name] for name in vehicle_names)) <= capacity, name='capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')